import type {
  AnalysisResponse,
  CompareResponse,
  CorrelationMatrix,
  MonteCarloResult,
  PortfolioMetrics,
} from "@/shared/types";

import type { ChartAnalysis } from "../analysisRows";

import analysisJson from "./analysis.json";
import compareJson from "./compare.json";
import correlationJson from "./correlation.json";
import monteCarloJson from "./monte-carlo.json";
import metricsJson from "./portfolio-metrics.json";

// Generated by `npm run gen:chart-fixtures` — edit the script, not the JSON.

export type AnalysisFixture = ChartAnalysis & Pick<AnalysisResponse, "symbol" | "support_resistance" | "fibonacci">;

export const analysisFixture = analysisJson as unknown as AnalysisFixture;
export const compareFixture = compareJson as unknown as CompareResponse;
export const correlationFixture = correlationJson as unknown as CorrelationMatrix;
export const monteCarloFixture = monteCarloJson as unknown as MonteCarloResult;
export const allocationFixture = (metricsJson as unknown as Pick<PortfolioMetrics, "sector_allocation">)
  .sector_allocation;

/** The web compare page's series building: one entry per symbol that has data. */
export function compareSeries(r: CompareResponse): { symbol: string; values: (number | null)[] }[] {
  return r.symbols
    .filter((symbol) => Array.isArray(r[symbol]))
    .map((symbol) => ({ symbol, values: r[symbol] as (number | null)[] }));
}
